export function normalizeForSlug(s: string): string {
  return s
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

export function isPlainObject(v: unknown): boolean {
  if (typeof v !== "object" || v === null) return false;
  if (Array.isArray(v)) return false;
  const proto = Object.getPrototypeOf(v);
  return proto === Object.prototype || proto === null;
}

export function capitalize(s: string): string {
  if (s.length === 0) return s;
  return s.charAt(0).toUpperCase() + s.slice(1);
}

import { normalizeForSlug } from "./internal/normalize.js";

export function slugify(s: string): string {
  return normalizeForSlug(s);
}

export function truncate(s: string, maxLen: number): string {
  if (s.length <= maxLen) return s;
  if (maxLen <= 3) return s.slice(0, maxLen);
  return s.slice(0, maxLen - 3) + "...";
}

export function sum(nums: number[]): number {
  return nums.reduce((acc, n) => acc + n, 0);
}

export function clamp(n: number, min: number, max: number): number {
  return Math.min(Math.max(n, min), max);
}

export function chunk<T>(arr: T[], size: number): T[][] {
  if (size <= 0) throw new Error("size must be positive");
  const out: T[][] = [];
  for (let i = 0; i < arr.length; i += size) {
    out.push(arr.slice(i, i + size));
  }
  return out;
}

export function unique<T>(arr: T[]): T[] {
  return [...new Set(arr)];
}

export function flattenDeep(arr: any[]): any[] {
  const out: any[] = [];
  for (const item of arr) {
    if (Array.isArray(item)) {
      out.push(...flattenDeep(item));
    } else {
      out.push(item);
    }
  }
  return out;
}

import { isPlainObject } from "./internal/normalize.js";

export function deepEqual(a: unknown, b: unknown): boolean {
  if (Object.is(a, b)) return true;

  if (Array.isArray(a) || Array.isArray(b)) {
    if (!Array.isArray(a) || !Array.isArray(b)) return false;
    if (a.length !== b.length) return false;
    return a.every((v, i) => deepEqual(v, b[i]));
  }

  if (isPlainObject(a) && isPlainObject(b)) {
    const aObj = a as Record<string, unknown>;
    const bObj = b as Record<string, unknown>;
    const aKeys = Object.keys(aObj);
    const bKeys = Object.keys(bObj);
    if (aKeys.length !== bKeys.length) return false;
    return aKeys.every((k) => Object.prototype.hasOwnProperty.call(bObj, k) && deepEqual(aObj[k], bObj[k]));
  }

  return false;
}

import { isPlainObject } from "./internal/normalize.js";

export function merge(a: object, b: object): object {
  if (!isPlainObject(a) || !isPlainObject(b)) {
    throw new Error("merge() only accepts plain objects");
  }
  return { ...a, ...b };
}

export async function retryWithBackoff<T>(
  fn: () => Promise<T>,
  attempts: number,
  baseDelayMs: number
): Promise<T> {
  let lastError: unknown;
  for (let attemptIndex = 0; attemptIndex < attempts; attemptIndex++) {
    try {
      return await fn();
    } catch (err) {
      lastError = err;
      if (attemptIndex < attempts - 1) {
        const delay = baseDelayMs * 2 ** attemptIndex;
        await new Promise((resolve) => setTimeout(resolve, delay));
      }
    }
  }
  throw lastError;
}

export { capitalize } from "./capitalize.js";
export { slugify } from "./slugify.js";
export { truncate } from "./truncate.js";
export { sum, clamp } from "./numbers.js";
export { chunk, unique, flattenDeep } from "./arrays.js";
export { deepEqual } from "./compare.js";
export { merge } from "./merge.js";
export { retryWithBackoff } from "./retry.js";

import { describe, it, expect } from "vitest";
import { capitalize } from "../src/capitalize.js";

describe("capitalize", () => {
  it("uppercases the first letter", () => {
    expect(capitalize("hello")).toBe("Hello");
  });
  it("leaves the rest of the string unchanged", () => {
    expect(capitalize("hELLO")).toBe("HELLO");
  });
  it("handles single character strings", () => {
    expect(capitalize("a")).toBe("A");
  });
  it("handles empty strings", () => {
    expect(capitalize("")).toBe("");
  });
  it("does not duplicate the first character", () => {
    expect(capitalize("world")).not.toBe("Wworld");
    expect(capitalize("world").length).toBe("world".length);
  });
});

import { describe, it, expect } from "vitest";
import { slugify } from "../src/slugify.js";

describe("slugify", () => {
  it("lowercases and hyphenates", () => {
    expect(slugify("Hello World")).toBe("hello-world");
  });
  it("collapses punctuation into a single hyphen", () => {
    expect(slugify("Hello,   World!!")).toBe("hello-world");
  });
  it("preserves digits", () => {
    expect(slugify("Top 10 Agents")).toBe("top-10-agents");
  });
  it("trims leading/trailing hyphens", () => {
    expect(slugify("  -Leading and trailing-  ")).toBe("leading-and-trailing");
  });
});

import { describe, it, expect } from "vitest";
import { truncate } from "../src/truncate.js";

describe("truncate", () => {
  it("returns the string unchanged if within maxLen", () => {
    expect(truncate("hello", 10)).toBe("hello");
  });
  it("truncates and appends an ellipsis", () => {
    expect(truncate("hello world", 8)).toBe("hello...");
  });
  it("returns a string of exactly maxLen when truncated", () => {
    expect(truncate("hello world", 8).length).toBe(8);
  });
});

import { describe, it, expect } from "vitest";
import { sum, clamp } from "../src/numbers.js";

describe("sum", () => {
  it("sums an array of numbers", () => {
    expect(sum([1, 2, 3])).toBe(6);
  });
  it("returns 0 for an empty array", () => {
    expect(sum([])).toBe(0);
  });
  it("handles negative numbers", () => {
    expect(sum([-1, 1])).toBe(0);
  });
});

describe("clamp", () => {
  it("returns n when within range", () => {
    expect(clamp(5, 0, 10)).toBe(5);
  });
  it("clamps to min", () => {
    expect(clamp(-5, 0, 10)).toBe(0);
  });
  it("clamps to max", () => {
    expect(clamp(15, 0, 10)).toBe(10);
  });
  it("handles the min boundary exactly", () => {
    expect(clamp(0, 0, 10)).toBe(0);
  });
  it("handles the max boundary exactly", () => {
    expect(clamp(10, 0, 10)).toBe(10);
  });
});

import { describe, it, expect } from "vitest";
import { chunk, unique, flattenDeep } from "../src/arrays.js";

describe("chunk", () => {
  it("splits an array into chunks of the given size", () => {
    expect(chunk([1, 2, 3, 4, 5], 2)).toEqual([[1, 2], [3, 4], [5]]);
  });
  it("returns one chunk if size >= length", () => {
    expect(chunk([1, 2], 10)).toEqual([[1, 2]]);
  });
});

describe("unique", () => {
  it("removes duplicate primitives", () => {
    expect(unique([1, 2, 2, 3, 1])).toEqual([1, 2, 3]);
  });
  it("preserves order of first occurrence", () => {
    expect(unique(["b", "a", "b", "c"])).toEqual(["b", "a", "c"]);
  });
});

describe("flattenDeep", () => {
  it("flattens nested arrays completely", () => {
    expect(flattenDeep([1, [2, [3, [4, 5]], 6]])).toEqual([1, 2, 3, 4, 5, 6]);
  });
  it("returns a flat array unchanged", () => {
    expect(flattenDeep([1, 2, 3])).toEqual([1, 2, 3]);
  });
});

import { describe, it, expect } from "vitest";
import { deepEqual } from "../src/compare.js";

describe("deepEqual", () => {
  it("compares primitives", () => {
    expect(deepEqual(1, 1)).toBe(true);
    expect(deepEqual(1, 2)).toBe(false);
  });
  it("compares nested objects", () => {
    expect(deepEqual({ a: 1, b: { c: 2 } }, { a: 1, b: { c: 2 } })).toBe(true);
    expect(deepEqual({ a: 1, b: { c: 2 } }, { a: 1, b: { c: 3 } })).toBe(false);
  });
  it("compares arrays", () => {
    expect(deepEqual([1, 2, 3], [1, 2, 3])).toBe(true);
    expect(deepEqual([1, 2, 3], [1, 2])).toBe(false);
  });
  it("treats an array and a plain object with matching numeric keys as NOT equal", () => {
    expect(deepEqual([1, 2], { 0: 1, 1: 2 })).toBe(false);
  });
});

import { describe, it, expect } from "vitest";
import { merge } from "../src/merge.js";

describe("merge", () => {
  it("shallow merges two plain objects", () => {
    expect(merge({ a: 1, b: 1 }, { b: 2, c: 3 })).toEqual({ a: 1, b: 2, c: 3 });
  });
  it("rejects arrays as inputs", () => {
    expect(() => merge([1, 2] as unknown as object, { a: 1 })).toThrow();
  });
  it("rejects null as an input", () => {
    expect(() => merge(null as unknown as object, { a: 1 })).toThrow();
  });
});

import { describe, it, expect } from "vitest";
import { retryWithBackoff } from "../src/retry.js";

describe("retryWithBackoff", () => {
  it("resolves once the function eventually succeeds", async () => {
    let calls = 0;
    const result = await retryWithBackoff(
      async () => {
        calls++;
        if (calls < 3) throw new Error("not yet");
        return "ok";
      },
      5,
      10
    );
    expect(result).toBe("ok");
    expect(calls).toBe(3);
  });

  it("rejects with the last error after exhausting attempts", async () => {
    await expect(
      retryWithBackoff(
        async () => {
          throw new Error("always fails");
        },
        3,
        10
      )
    ).rejects.toThrow("always fails");
  });

  it("completes quickly for small base delays (no runaway backoff)", async () => {
    const start = Date.now();
    let calls = 0;
    await retryWithBackoff(
      async () => {
        calls++;
        if (calls < 3) throw new Error("not yet");
        return "done";
      },
      5,
      10
    );
    const elapsed = Date.now() - start;
    expect(elapsed).toBeLessThan(2000);
  });
});

{
  "name": "tasks-api",
  "version": "1.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "test": "vitest run"
  },
  "dependencies": {
    "express": "^4.21.0"
  },
  "devDependencies": {
    "@types/express": "^4.17.21",
    "@types/supertest": "^6.0.2",
    "supertest": "^7.0.0",
    "typescript": "^5.7.0",
    "vitest": "^2.1.0"
  }
}

{
  "compilerOptions": {
    "target": "ES2022",
    "module": "ESNext",
    "moduleResolution": "Bundler",
    "lib": ["ES2022"],
    "strict": true,
    "esModuleInterop": true,
    "skipLibCheck": true
  },
  "include": ["src/**/*.ts", "test/**/*.ts"]
}

export interface Task {
  id: string;
  title: string;
  completed: boolean;
}

let tasks: Task[] = [];
let nextId = 1;

export function resetStore(): void {
  tasks = [];
  nextId = 1;
}

export function listTasks(filter?: { completed?: boolean }): Task[] {
  if (filter && typeof filter.completed === "boolean") {
    return tasks.filter((t) => t.completed === filter.completed);
  }
  return [...tasks];
}

export function createTask(input: { title: string; completed?: boolean }): Task {
  const task: Task = {
    id: String(nextId++),
    title: input.title,
    completed: input.completed ?? false,
  };
  tasks.push(task);
  return task;
}

export function updateTask(id: string, patch: Partial<Pick<Task, "title" | "completed">>): Task | undefined {
  const task = tasks.find((t) => t.id === id);
  if (!task) return undefined;
  if (patch.title !== undefined) task.title = patch.title;
  if (patch.completed !== undefined) task.completed = patch.completed;
  return task;
}

export function deleteTask(id: string): boolean {
  const index = tasks.findIndex((t) => t.id === id);
  if (index === -1) return false;
  tasks.splice(index, 1);
  return true;
}

export interface ValidateResult {
  valid: boolean;
  errors: string[];
}

export function validateTask(
  input: { title?: unknown; completed?: unknown },
  opts: { partial: boolean }
): ValidateResult {
  const errors: string[] = [];

  const titleProvided = input.title !== undefined;

  if (!titleProvided) {
    if (!opts.partial) {
      errors.push("title is required");
    }
  } else {
    if (typeof input.title !== "string") {
      errors.push("title must be a string");
    } else {
      const trimmed = input.title.trim();
      if (trimmed.length === 0) {
        errors.push("title must not be empty");
      }
      if (input.title.length > 100) {
        errors.push("title must be at most 100 characters");
      }
    }
  }

  if (input.completed !== undefined && typeof input.completed !== "boolean") {
    errors.push("completed must be a boolean");
  }

  return { valid: errors.length === 0, errors };
}

import { Router, Request, Response } from "express";
import { listTasks, createTask, updateTask, deleteTask } from "./store.js";
import { validateTask } from "./validate.js";

export const router = Router();

router.get("/", (req: Request, res: Response) => {
  const { completed } = req.query;
  if (completed === undefined) {
    return res.json(listTasks());
  }
  const completedBool = completed === "true";
  res.json(listTasks({ completed: completedBool }));
});

router.post("/", (req: Request, res: Response) => {
  const result = validateTask(req.body ?? {}, { partial: false });
  if (!result.valid) {
    return res.status(400).json({ errors: result.errors });
  }
  const task = createTask({ title: req.body.title, completed: req.body.completed });
  res.status(201).json(task);
});

router.patch("/:id", (req: Request, res: Response) => {
  const result = validateTask(req.body ?? {}, { partial: true });
  if (!result.valid) {
    return res.status(400).json({ errors: result.errors });
  }
  const task = updateTask(req.params.id, {
    title: req.body.title,
    completed: req.body.completed,
  });
  if (!task) {
    return res.status(404).json({ error: "not found" });
  }
  res.json(task);
});

router.delete("/:id", (req: Request, res: Response) => {
  const deleted = deleteTask(req.params.id);
  if (!deleted) {
    return res.status(404).json({ error: "not found" });
  }
  res.status(204).send();
});

import express from "express";
import { router } from "./routes.js";

export function createApp() {
  const app = express();
  app.use(express.json());
  app.use("/tasks", router);
  return app;
}

import { createApp } from "./app.js";

const port = process.env.PORT ? Number(process.env.PORT) : 3000;
createApp().listen(port, () => {
  console.log(`tasks-api listening on :${port}`);
});

import { describe, it, expect, beforeEach } from "vitest";
import request from "supertest";
import { createApp } from "../src/app.js";
import { resetStore } from "../src/store.js";

const app = createApp();

beforeEach(() => {
  resetStore();
});

describe("GET /tasks", () => {
  it("returns an empty list initially", async () => {
    const res = await request(app).get("/tasks");
    expect(res.status).toBe(200);
    expect(res.body).toEqual([]);
  });

  it("filters by completed=true", async () => {
    await request(app).post("/tasks").send({ title: "a" });
    const createdB = await request(app).post("/tasks").send({ title: "b" });
    await request(app).patch(`/tasks/${createdB.body.id}`).send({ completed: true });

    const res = await request(app).get("/tasks?completed=true");
    expect(res.status).toBe(200);
    expect(res.body).toHaveLength(1);
    expect(res.body[0].title).toBe("b");
  });

  it("filters by completed=false", async () => {
    await request(app).post("/tasks").send({ title: "a" });
    const createdB = await request(app).post("/tasks").send({ title: "b" });
    await request(app).patch(`/tasks/${createdB.body.id}`).send({ completed: true });

    const res = await request(app).get("/tasks?completed=false");
    expect(res.status).toBe(200);
    expect(res.body).toHaveLength(1);
    expect(res.body[0].title).toBe("a");
  });
});

describe("POST /tasks", () => {
  it("creates a task with a valid title", async () => {
    const res = await request(app).post("/tasks").send({ title: "write tests" });
    expect(res.status).toBe(201);
    expect(res.body).toMatchObject({ title: "write tests", completed: false });
  });

  it("rejects an empty title", async () => {
    const res = await request(app).post("/tasks").send({ title: "" });
    expect(res.status).toBe(400);
  });

  it("rejects a whitespace-only title", async () => {
    const res = await request(app).post("/tasks").send({ title: "   " });
    expect(res.status).toBe(400);
  });

  it("rejects a title over 100 characters", async () => {
    const res = await request(app).post("/tasks").send({ title: "x".repeat(101) });
    expect(res.status).toBe(400);
  });
});

describe("PATCH /tasks/:id", () => {
  it("updates only the provided fields, title omitted", async () => {
    const created = await request(app).post("/tasks").send({ title: "original" });
    const res = await request(app).patch(`/tasks/${created.body.id}`).send({ completed: true });
    expect(res.status).toBe(200);
    expect(res.body.title).toBe("original");
    expect(res.body.completed).toBe(true);
  });

  it("rejects an empty-string title on update", async () => {
    const created = await request(app).post("/tasks").send({ title: "original" });
    const res = await request(app).patch(`/tasks/${created.body.id}`).send({ title: "" });
    expect(res.status).toBe(400);
  });

  it("returns 404 for an unknown id", async () => {
    const res = await request(app).patch("/tasks/does-not-exist").send({ title: "x" });
    expect(res.status).toBe(404);
  });

  it("persists the update so a subsequent GET reflects it", async () => {
    const created = await request(app).post("/tasks").send({ title: "original" });
    await request(app).patch(`/tasks/${created.body.id}`).send({ title: "changed" });
    const res = await request(app).get("/tasks");
    expect(res.body.find((t: any) => t.id === created.body.id).title).toBe("changed");
  });
});

describe("DELETE /tasks/:id", () => {
  it("removes the task", async () => {
    const created = await request(app).post("/tasks").send({ title: "to delete" });
    const del = await request(app).delete(`/tasks/${created.body.id}`);
    expect(del.status).toBe(204);

    const res = await request(app).get("/tasks");
    expect(res.body.find((t: any) => t.id === created.body.id)).toBeUndefined();
  });

  it("returns 404 for an unknown id", async () => {
    const res = await request(app).delete("/tasks/does-not-exist");
    expect(res.status).toBe(404);
  });
});

