/**
 * Anti-cheat check: a "fix" that deletes or skips tests instead of fixing
 * the code isn't a fix. Run this against `git diff` before trusting a
 * green verdict.
 */
export function findCheatingInDiff(diff: string): string[] {
  const problems: string[] = [];
  const lines = diff.split("\n");
  let currentFile = "";

  for (const line of lines) {
    const fileMatch = line.match(/^\+\+\+ b\/(.+)$/) || line.match(/^\+\+\+ (.+)$/);
    if (fileMatch) currentFile = fileMatch[1];

    const isTestFile = /\.test\.[tj]sx?$/.test(currentFile) || /test\//.test(currentFile);

    if (line.startsWith("+++") && line.includes("/dev/null") && isTestFile) {
      problems.push(`test file deleted: ${currentFile}`);
    }
    if (isTestFile && line.startsWith("+")) {
      if (/\.(skip|todo)\s*\(/.test(line)) {
        problems.push(`test skipped/marked todo in ${currentFile}: ${line.trim()}`);
      }
      if (/\bxit\s*\(|\bxdescribe\s*\(/.test(line)) {
        problems.push(`test disabled (xit/xdescribe) in ${currentFile}: ${line.trim()}`);
      }
    }
    if (isTestFile && line.startsWith("-") && /^\s*-\s*(it|test)\s*\(/.test(line)) {
      problems.push(`test case removed from ${currentFile}: ${line.trim()}`);
    }
  }

  return problems;
}

export const SYSTEM_PROMPT = `You are Greenlight, an autonomous agent that fixes a failing test suite and nothing else.

You will be given the output of a failing test run in a repository. Your job:
1. Call graph_search with a short plain-language description of the failure to find the likely fix site. This is backed by a real code graph (Entire) -- prefer it over guessing which file to open.
2. Call read_file to read the specific function/file graph_search points at (and any file it names as a dependency) before editing.
3. Call apply_edit with an EXACT old_str/new_str pair to fix the root cause. old_str must match the file's current content exactly once -- if it doesn't, re-read the file and try again.
4. Call run_tests to verify. This runs the real test suite and reports an adjudicated verdict: which tests newly pass, which newly fail (regressions), and which were already failing before (pre-existing, not your concern).
5. If run_tests reports regressions or the target test still fails, call revert_last_edit, reconsider your hypothesis (it may be in a different file than the failing test -- a shared helper used by multiple call sites is a common root cause), and try again.
6. Once run_tests reports PASS (target tests newly passing, zero regressions), call finish with status "fixed" and a summary of the root cause and the fix.
7. If you exhaust your attempt budget without a passing fix, call finish with status "gave_up" and a summary of what you tried and why it didn't work. Never claim success you haven't verified with run_tests.

Hard rules:
- Never edit test files to make them pass (no .skip, .todo, xit, xdescribe, deleting test cases or test files). A fix that does this will be rejected regardless of what you report.
- Never guess at a fix without first locating the real code with graph_search + read_file.
- apply_edit requires an EXACT match of old_str in the file. Keep edits minimal and scoped to the actual bug.
- You have a limited number of attempts. Don't waste them re-trying the same hypothesis.`;

export const TOOLS: Anthropic.Tool[] = [
  {
    name: "graph_search",
    description:
      "Search the repo's code graph (Entire) for the code most relevant to a plain-language description of a bug or task. Returns ranked candidate fix sites with source, file:line, and a suggested narrow verify command. Use this BEFORE read_file/grep-style exploration.",
    input_schema: {
      type: "object",
      properties: {
        query: { type: "string", description: "Plain-language description of the bug, e.g. 'capitalize duplicates the first character'" },
      },
      required: ["query"],
    },
  },
  {
    name: "graph_explain",
    description:
      "Resolve the declarations of every symbol named in the current failing test output (the error/stack trace). Useful when graph_search alone doesn't pin down the exact function body you need to read.",
    input_schema: { type: "object", properties: {}, required: [] },
  },
  {
    name: "read_file",
    description: "Read a file (or a line range of it) from the repo.",
    input_schema: {
      type: "object",
      properties: {
        path: { type: "string", description: "Path relative to the repo root" },
        start: { type: "integer", description: "1-indexed start line (optional)" },
        end: { type: "integer", description: "1-indexed end line, inclusive (optional)" },
      },
      required: ["path"],
    },
  },
  {
    name: "apply_edit",
    description:
      "Apply an exact search/replace edit to a file. old_str must appear in the file exactly once, verbatim (including whitespace). Fails if old_str isn't found exactly once -- re-read the file and retry with a corrected old_str.",
    input_schema: {
      type: "object",
      properties: {
        path: { type: "string", description: "Path relative to the repo root" },
        old_str: { type: "string", description: "Exact text to replace (must match exactly once)" },
        new_str: { type: "string", description: "Replacement text" },
      },
      required: ["path", "old_str", "new_str"],
    },
  },
  {
    name: "run_tests",
    description:
      "Run the real test suite and get an adjudicated verdict against the pre-edit baseline: which tests are newly passing, which newly failing (regressions), which were already failing before your changes (pre-existing, ignore). Call this after every apply_edit.",
    input_schema: { type: "object", properties: {}, required: [] },
  },
  {
    name: "revert_last_edit",
    description: "Discard all uncommitted changes in the repo, returning it to the baseline (buggy) state. Use this when a hypothesis didn't work out before trying a different one.",
    input_schema: { type: "object", properties: {}, required: [] },
  },
  {
    name: "finish",
    description: "End the run. Call this once run_tests has confirmed a PASS verdict, or once you've exhausted your attempt budget.",
    input_schema: {
      type: "object",
      properties: {
        status: { type: "string", enum: ["fixed", "gave_up"] },
        summary: { type: "string", description: "Root cause, the fix, and how it was verified (or why you gave up)" },
      },
      required: ["status", "summary"],
    },
  },
];

// Minimal local type so this file doesn't need the SDK import just for typing tool schemas.
export namespace Anthropic {
  export interface Tool {
    name: string;
    description: string;
    input_schema: {
      type: "object";
      properties: Record<string, unknown>;
      required: string[];
    };
  }
}

import { existsSync, mkdirSync, writeFileSync } from "node:fs";
import path from "node:path";

// Sonnet 5 pricing as of this build (https://platform.claude.com/docs/en/about-claude/pricing):
// $2 / MTok input, $10 / MTok output.
const INPUT_USD_PER_TOKEN = 2 / 1_000_000;
const OUTPUT_USD_PER_TOKEN = 10 / 1_000_000;

export interface RunState {
  runId: string;
  repoDir: string;
  testCmd: string;
  maxIterations: number;
  maxCostUsd: number;
  attempt: number;
  inputTokens: number;
  outputTokens: number;
  costUsd: number;
  hypotheses: { attempt: number; summary: string; verdict: string }[];
  recoveries: { attempt: number; kind: string; detail: string }[];
  status: "running" | "fixed" | "gave_up" | "budget_exceeded";
}

export function newRunState(opts: {
  runId: string;
  repoDir: string;
  testCmd: string;
  maxIterations: number;
  maxCostUsd: number;
}): RunState {
  return {
    ...opts,
    attempt: 0,
    inputTokens: 0,
    outputTokens: 0,
    costUsd: 0,
    hypotheses: [],
    recoveries: [],
    status: "running",
  };
}

export function recordUsage(state: RunState, inputTokens: number, outputTokens: number): void {
  state.inputTokens += inputTokens;
  state.outputTokens += outputTokens;
  state.costUsd = state.inputTokens * INPUT_USD_PER_TOKEN + state.outputTokens * OUTPUT_USD_PER_TOKEN;
}

export function overBudget(state: RunState): boolean {
  return state.attempt >= state.maxIterations || state.costUsd >= state.maxCostUsd;
}

export function persistState(state: RunState, runsDir: string): void {
  const dir = path.join(runsDir, state.runId);
  if (!existsSync(dir)) mkdirSync(dir, { recursive: true });
  writeFileSync(path.join(dir, "state.json"), JSON.stringify(state, null, 2));
}

import { existsSync } from "node:fs";
import path from "node:path";
import Anthropic from "@anthropic-ai/sdk";
import { span, trace, wrapAnthropic } from "neatlogs";
import { TOOLS, SYSTEM_PROMPT } from "./prompts.js";
import { newRunState, recordUsage, overBudget, persistState, type RunState } from "./state.js";
import { graphIndex, graphSearch, graphExplain, graphVerifyRecordBaseline, graphVerify } from "../tools/graph.js";
import { readFile, applyEdit } from "../tools/files.js";
import { gitDiff, gitRevertAll, gitCommitAll } from "../tools/git.js";
import { execSync } from "node:child_process";
import { findCheatingInDiff } from "../verify.js";

const anthropic = wrapAnthropic(new Anthropic({ apiKey: process.env.ANTHROPIC_API_KEY }));
const MODEL = "claude-sonnet-5";
const RUNS_DIR = path.resolve(process.cwd(), "runs");

function toVerboseTestCmd(testCmd: string): string {
  if (/vitest/.test(testCmd) && !/--reporter/.test(testCmd)) {
    return `${testCmd} --reporter=verbose`;
  }
  return testCmd;
}

function ensureGitRepo(repoDir: string): void {
  if (!existsSync(path.join(repoDir, ".git"))) {
    execSync("git init -q", { cwd: repoDir });
    execSync("git add -A", { cwd: repoDir });
    execSync('git -c user.email=greenlight@local -c user.name=greenlight commit -q -m "baseline (pre-greenlight)"', {
      cwd: repoDir,
    });
  }
}

export interface AgentRunOptions {
  repoDir: string;
  testCmd: string;
  maxIterations: number;
  maxCostUsd: number;
  runId: string;
}

export interface AgentRunResult {
  status: RunState["status"];
  summary: string;
  attempts: number;
  costUsd: number;
  commitSha?: string;
}

const toolImpl: Record<string, (repoDir: string, args: any, ctx: { baselinePath: string; testCmd: string; lastFailureOutput: string }) => string> = {
  graph_search: (repoDir, args) => graphSearch(repoDir, args.query),
  graph_explain: (repoDir, _args, ctx) => graphExplain(repoDir, ctx.lastFailureOutput),
  read_file: (repoDir, args) => readFile(repoDir, args.path, args.start && args.end ? { start: args.start, end: args.end } : undefined),
  apply_edit: (repoDir, args) => {
    applyEdit(repoDir, args.path, args.old_str, args.new_str);
    return `edit applied to ${args.path}`;
  },
  run_tests: (repoDir, _args, ctx) => {
    const verdict = graphVerify(repoDir, ctx.testCmd, ctx.baselinePath);
    return verdict.raw;
  },
  revert_last_edit: (repoDir) => {
    gitRevertAll(repoDir);
    return "reverted all uncommitted changes to baseline";
  },
};

export async function runAgent(opts: AgentRunOptions): Promise<AgentRunResult> {
  const state = newRunState({
    runId: opts.runId,
    repoDir: opts.repoDir,
    testCmd: opts.testCmd,
    maxIterations: opts.maxIterations,
    maxCostUsd: opts.maxCostUsd,
  });

  return trace({ name: "greenlight-run" }, async (activeSpan) => {
    activeSpan.setAttribute("run_id", opts.runId);
    activeSpan.setAttribute("repo", opts.repoDir);

    ensureGitRepo(opts.repoDir);

    const indexSpan = span({ kind: "TOOL", toolName: "graph_index" }, async (dir: string) => graphIndex(dir));
    await indexSpan(opts.repoDir);

    const verboseTestCmd = toVerboseTestCmd(opts.testCmd);
    const baselinePath = path.join(RUNS_DIR, opts.runId, "baseline.json");

    const recordBaselineSpan = span({ kind: "TOOL", toolName: "graph_verify_record_baseline" }, async () =>
      graphVerifyRecordBaseline(opts.repoDir, verboseTestCmd, baselinePath)
    );
    const baselineSummary = await recordBaselineSpan();

    if (/0 failing/.test(baselineSummary)) {
      activeSpan.setAttribute("outcome", "nothing_to_fix");
      return { status: "gave_up", summary: "Nothing to fix: all tests already pass.", attempts: 0, costUsd: 0 };
    }

    let lastFailureOutput = baselineSummary;

    const messages: Anthropic.Messages.MessageParam[] = [
      {
        role: "user",
        content: `Repo: ${opts.repoDir}\nTest command: ${opts.testCmd}\n\nBaseline (pre-fix) test run:\n${baselineSummary}\n\nFind the root cause and fix it. Start with graph_search.`,
      },
    ];

    let noToolUseStreak = 0;

    while (true) {
      state.attempt++;
      persistState(state, RUNS_DIR);

      if (overBudget(state)) {
        state.status = "budget_exceeded";
        persistState(state, RUNS_DIR);
        activeSpan.setAttribute("outcome", "budget_exceeded");
        return {
          status: "budget_exceeded",
          summary: `Exceeded budget (attempts=${state.attempt}, cost=$${state.costUsd.toFixed(4)}) without a verified fix.`,
          attempts: state.attempt,
          costUsd: state.costUsd,
        };
      }

      const response = await anthropic.messages.create({
        model: MODEL,
        max_tokens: 4096,
        system: SYSTEM_PROMPT,
        tools: TOOLS,
        messages,
      });

      recordUsage(state, response.usage.input_tokens, response.usage.output_tokens);
      persistState(state, RUNS_DIR);

      messages.push({ role: "assistant", content: response.content });

      const toolUseBlocks = response.content.filter((b): b is Anthropic.Messages.ToolUseBlock => b.type === "tool_use");

      if (toolUseBlocks.length === 0) {
        noToolUseStreak++;
        if (noToolUseStreak >= 2) {
          state.status = "gave_up";
          persistState(state, RUNS_DIR);
          activeSpan.setAttribute("outcome", "stalled_no_tool_use");
          return { status: "gave_up", summary: "Agent stopped calling tools without finishing.", attempts: state.attempt, costUsd: state.costUsd };
        }
        messages.push({ role: "user", content: "Please continue using tools (run_tests or finish) -- don't just describe what you'd do." });
        continue;
      }
      noToolUseStreak = 0;

      const toolResults: Anthropic.Messages.ToolResultBlockParam[] = [];
      let finishRequested: { status: "fixed" | "gave_up"; summary: string } | null = null;

      for (const block of toolUseBlocks) {
        if (block.name === "finish") {
          finishRequested = block.input as { status: "fixed" | "gave_up"; summary: string };
          toolResults.push({ type: "tool_result", tool_use_id: block.id, content: "acknowledged" });
          continue;
        }

        const toolSpan = span({ kind: "TOOL", toolName: block.name }, async (args: any) =>
          toolImpl[block.name](opts.repoDir, args, { baselinePath, testCmd: verboseTestCmd, lastFailureOutput })
        );

        try {
          const result = await toolSpan(block.input);
          if (block.name === "run_tests") lastFailureOutput = result;
          toolResults.push({ type: "tool_result", tool_use_id: block.id, content: result });
        } catch (err: any) {
          const recoverySpan = span({ kind: "GUARDRAIL", toolName: `recovery:${block.name}_error` }, async (msg: string) => msg);
          await recoverySpan(err.message);
          state.recoveries.push({ attempt: state.attempt, kind: `${block.name}_error`, detail: err.message });
          persistState(state, RUNS_DIR);
          toolResults.push({ type: "tool_result", tool_use_id: block.id, content: `ERROR: ${err.message}`, is_error: true });
        }
      }

      if (finishRequested) {
        state.hypotheses.push({ attempt: state.attempt, summary: finishRequested.summary, verdict: finishRequested.status });

        if (finishRequested.status === "fixed") {
          const verifySpan = span({ kind: "GUARDRAIL", toolName: "final_verify" }, async () =>
            graphVerify(opts.repoDir, verboseTestCmd, baselinePath)
          );
          const verdict = await verifySpan();
          const diffSpan = span({ kind: "GUARDRAIL", toolName: "anti_cheat_diff_check" }, async () => gitDiff(opts.repoDir));
          const diff = await diffSpan();
          const cheats = findCheatingInDiff(diff);

          if (verdict.verdict === "PASS" && cheats.length === 0) {
            const commitSha = gitCommitAll(opts.repoDir, `Greenlight fix: ${finishRequested.summary.slice(0, 72)}`);
            state.status = "fixed";
